namespace sv_5faf8378374a4b399c0fe073bbe6dffe.Services;

public sealed class Recipe
{
    public int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public int PrepTimeMinutes { get; init; }
}

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg, and parmesan.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored Italian dessert.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Sushi Rolls", Description = "Fresh fish and rice wrapped in seaweed.", PrepTimeMinutes = 40 },
            new() { Id = 5, Title = "Ramen", Description = "Rich broth with noodles, pork, and soft-boiled egg.", PrepTimeMinutes = 60 },
            new() { Id = 6, Title = "Tempura", Description = "Lightly battered and deep-fried seafood and vegetables.", PrepTimeMinutes = 20 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple and cilantro.", PrepTimeMinutes = 35 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime, onion, and tomato.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar.", PrepTimeMinutes = 25 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call.
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_5faf8378374a4b399c0fe073bbe6dffe.Services
@using Microsoft.AspNetCore.Components.Routing
@implements IDisposable
@rendermode InteractiveServer
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h3>Recipes — Cuisine #@CuisineId</h3>

@if (_sortOrder is "newest" or "popular")
{
    <p class="text-muted">Sorted by: @_sortOrder</p>
}

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2" role="status">Refreshing…</div>
    }

    @if (_recipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="list-group">
            @foreach (var recipe in _displayedRecipes)
            {
                <div class="list-group-item">
                    <h5>@recipe.Title</h5>
                    <p class="mb-1">@recipe.Description</p>
                    <small class="text-muted">Prep time: @recipe.PrepTimeMinutes min</small>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _sortOrder;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;

    private IReadOnlyList<Recipe> _displayedRecipes =>
        _sortOrder == "newest"
            ? _recipes!.OrderByDescending(r => r.Id).ToList()
            : _sortOrder == "popular"
                ? _recipes!.OrderBy(r => r.PrepTimeMinutes).ToList()
                : _recipes!;

    protected override Task OnInitializedAsync()
    {
        Navigation.LocationChanged += OnLocationChanged;
        return LoadRecipesAsync(CuisineId);
    }

    public override Task SetParametersAsync(ParameterView parameters)
    {
        // Capture the sort parameter on every parameter change (including query-only changes).
        if (parameters.TryGetValue<string>(nameof(Sort), out var sort))
        {
            _sortOrder = sort;
        }

        return base.SetParametersAsync(parameters);
    }

    protected override Task OnParametersSetAsync()
    {
        // Only reload when the cuisine actually changes.
        if (_loadedCuisineId != 0 && CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync(CuisineId);
        }

        return Task.CompletedTask;
    }

    private void OnLocationChanged(object? sender, LocationChangedEventArgs e)
    {
        // Re-parse sort from query string on every navigation so that
        // sort-only changes are picked up even when the framework
        // short-circuits parameter binding for same-page navigations.
        var uri = new Uri(e.Location);
        var query = Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query);
        _sortOrder = query.TryGetValue("sort", out var val) ? val.ToString() : null;
        InvokeAsync(StateHasChanged);
    }

    private async Task LoadRecipesAsync(int cuisineId)
    {
        // Cancel any in-flight load.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = new CancellationTokenSource();
        var token = _loadCts.Token;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        _loadedCuisineId = cuisineId;
        StateHasChanged();

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, token);

            token.ThrowIfCancellationRequested();

            _recipes = results;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // A newer load superseded this one — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private Task Retry() => LoadRecipesAsync(CuisineId);

    public void Dispose()
    {
        Navigation.LocationChanged -= OnLocationChanged;

        if (_loadCts is not null)
        {
            _loadCts.Cancel();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }
}

